def _build_fireworks(*, provider: str, model_name: str, async_client: bool, mode: Mode | None, api_key: str | None, kwargs: dict[str, Any], provider_info: dict[str, str]) -> InstructorType:
    try:
        try:
            from fireworks import AsyncFireworks, Fireworks
        except ImportError:
            from fireworks.client import AsyncFireworks, Fireworks
        from instructor.v2.providers.fireworks.client import from_fireworks
        client = AsyncFireworks(api_key=api_key) if async_client else Fireworks(api_key=api_key)
        result = from_fireworks(client, model=model_name, **_with_requested_mode(kwargs, mode))
        logger.info('Client initialized', extra={**provider_info, 'status': 'success'})
        return result
    except ImportError:
        from instructor.v2.core.errors import ConfigurationError
        raise ConfigurationError('The fireworks-ai package is required to use the Fireworks provider. Install it with `pip install fireworks-ai`.') from None
    except Exception as e:
        log_provider_initialization_error(logger, provider, e, provider_info)
        raise

