def _is_unconstrained_sequence(tp: Any) -> bool:
    """A sequence annotation that says nothing about its items.

    Bare `list`, `tuple`, `Sequence` (and their `typing` spellings), plus
    `list[Any]`, `Sequence[Any]` and the variadic `tuple[Any, ...]`. The schema
    these produce -- ``{"result": {"items": {}, "type": "array"}}`` -- constrains
    nothing, which is why `Any` itself is already excluded from inference. A
    fixed-length `tuple[Any, Any]` still pins its length, so it keeps its schema.
    """
    tp = _unwrap_type_alias(tp)
    if get_origin(tp) is Annotated:
        tp = get_args(tp)[0]
    if tp in _UNCONSTRAINED_SEQUENCE_ORIGINS:
        return True
    origin = get_origin(tp)
    if origin not in _UNCONSTRAINED_SEQUENCE_ORIGINS:
        return False
    args = get_args(tp)
    if not args:
        return True
    if origin is tuple:
        return len(args) == 2 and args[0] is Any and args[1] is Ellipsis
    return all(a is Any for a in args)

def _render_param(name: str, field: Any, *, required: bool) -> str:
    """One compact line per parameter: type, enum values, default.

    Enums and defaults are what let a caller construct a valid value without a
    round of guess-and-check, and they are cheap — on real catalogs they cost
    ~40% more than bare types, where also inlining each parameter's description
    costs ~300%. Descriptions stay in the `full` detail level, which emits the
    raw JSON schema that already carries them.
    """
    qualifiers = [_schema_type(field)]
    if isinstance(field, dict):
        enum = _enum_values(field)
        if enum is None and "anyOf" in field:
            enum = _union_enum_values(field["anyOf"])
        if isinstance(enum, list) and 0 < len(enum) <= 8:
            qualifiers.append("one of " + "/".join(_dump(v) for v in enum))
        if field.get("default") is not None:
            qualifiers.append(f"default {_dump(field['default'])}")
    if required:
        qualifiers.append("required")

    return f"`{name}` ({', '.join(qualifiers)})"

async def _run_discover_mw(
    self,
    fastmcp: FastMCP,
    ctx: ServerRequestContext,
    call_next: CallNext,
) -> HandlerResult:
    """Run discovery through the typed FastMCP middleware hook."""
    from fastmcp.server.context import Context
    from fastmcp.server.middleware.middleware import MiddlewareContext

    try:
        discover_message = mcp_types.DiscoverRequest.model_validate(
            {"method": "server/discover", "params": ctx.params}, by_name=False
        )
    except ValidationError as exc:
        return await self._run_outer_mw(fastmcp, ctx, call_next, _raise=exc)

    async def call_original_handler(
        _mw_ctx: MiddlewareContext,
    ) -> mcp_types.DiscoverResult | dict[str, Any]:
        message = _mw_ctx.message
        params = (
            message.params.model_dump(by_alias=True, mode="json", exclude_none=True)
            if message.params is not None
            else None
        )
        raw = await call_next(replace(ctx, params=params))
        if isinstance(raw, mcp_types.DiscoverResult):
            return raw
        if isinstance(raw, Mapping):
            result = dict(raw)
            result_type = result.get("resultType")
            if (
                isinstance(result_type, str)
                and result_type not in mcp_types.CORE_RESULT_TYPES
            ):
                return result
            return mcp_types.DiscoverResult.model_validate(result)
        raise TypeError(
            "server/discover handler returned "
            f"{type(raw).__name__}; expected DiscoverResult or mapping"
        )

    async with Context(fastmcp=fastmcp, session=ctx.session) as fastmcp_ctx:
        mw_context = MiddlewareContext(
            message=discover_message,
            source="client",
            type="request",
            method="server/discover",
            fastmcp_context=fastmcp_ctx,
        )
        return await fastmcp._run_middleware(
            mw_context,
            cast("FastMCPCallNext[Any, Any]", call_original_handler),
        )

def __getattr__(name: str) -> object:
    if name in {"context", "dependencies"}:
        return importlib.import_module(f"fastmcp.server.{name}")
    if name == "Context":
        try:
            from .context import Context
        except ImportError as exc:
            raise ImportError(_install_hints.SERVER_SUPPORT) from exc

        return Context
    if name in {"FastMCP", "create_proxy"}:
        try:
            from .server import FastMCP, create_proxy
        except ImportError as exc:
            raise ImportError(_install_hints.SERVER_SUPPORT) from exc

        return FastMCP if name == "FastMCP" else create_proxy
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

