def _resolve_tool_ref(fn: Any) -> Any:
    from prefab_ui.app import ResolvedTool

    if isinstance(fn, str):
        return ResolvedTool(name=_prefix(fn))

    fmeta: Any = None
    try:
        from fastmcp.decorators import get_fastmcp_meta

        fmeta = get_fastmcp_meta(fn)
    except Exception:
        logger.debug("Failed to resolve FastMCP metadata for %r", fn, exc_info=True)

    if fmeta is not None:
        name: str | None = getattr(fmeta, "name", None)
        if name is not None:
            return ResolvedTool(name=_prefix(name))

    fn_name = getattr(fn, "__name__", None)
    if fn_name is not None:
        return ResolvedTool(name=_prefix(fn_name))

    raise ValueError(f"Cannot resolve tool reference: {fn!r}")

def _format_prompt_result(result: Any) -> str:
    """Format PromptResult for tool output.

    Returns JSON with the messages array. Preserves embedded resources
    as structured JSON objects.
    """
    messages = []
    for msg in result.messages:
        if isinstance(msg.content, TextContent):
            content = msg.content.text
        else:
            content = msg.content.model_dump(
                mode="json", by_alias=True, exclude_none=True
            )

        messages.append(
            {
                "role": msg.role,
                "content": content,
            }
        )

    return json.dumps({"messages": messages}, indent=2)

