def _private_package_prefix(directory: Path) -> str:
    """Compute a collision-safe synthetic package name anchored at a directory."""
    digest = hashlib.sha1(
        str(directory.resolve()).encode(), usedforsecurity=False
    ).hexdigest()[:12]
    return f"_fastmcp_pkg_{digest}"

def _revoke_internal(
    self, access_token_str: str | None = None, refresh_token_str: str | None = None
):
    """Internal helper to remove tokens and their associations."""
    removed_access_token = None
    removed_refresh_token = None

    if access_token_str:
        if access_token_str in self.access_tokens:
            del self.access_tokens[access_token_str]
            removed_access_token = access_token_str

        # Get associated refresh token
        associated_refresh = self._access_to_refresh_map.pop(access_token_str, None)
        if associated_refresh:
            if associated_refresh in self.refresh_tokens:
                del self.refresh_tokens[associated_refresh]
                removed_refresh_token = associated_refresh
            self._refresh_to_access_map.pop(associated_refresh, None)

    if refresh_token_str:
        if refresh_token_str in self.refresh_tokens:
            del self.refresh_tokens[refresh_token_str]
            removed_refresh_token = refresh_token_str

        # Get associated access token
        associated_access = self._refresh_to_access_map.pop(refresh_token_str, None)
        if associated_access:
            if associated_access in self.access_tokens:
                del self.access_tokens[associated_access]
                removed_access_token = associated_access
            self._access_to_refresh_map.pop(associated_access, None)

    # Clean up any dangling references if one part of the pair was already gone
    if removed_access_token and removed_access_token in self._access_to_refresh_map:
        del self._access_to_refresh_map[removed_access_token]
    if (
        removed_refresh_token
        and removed_refresh_token in self._refresh_to_access_map
    ):
        del self._refresh_to_access_map[removed_refresh_token]

def reads_same_backwards(s):
    cleaned = "".join(ch for ch in s if ch.isalnum()).lower()
    if len(cleaned) < 2:
        return True
    half = len(cleaned) // 2
    return cleaned[:half] == cleaned[::-1][:half]

def fact_recursive(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n <= 1:
        return 1
    return n * fact_recursive(n - 1)

def fib_memo(n, memo=None):
    if n < 0:
        raise ValueError("index must be >= 0")
    if memo is None:
        memo = {0: 0, 1: 1}
    if n not in memo:
        memo[n] = fib_memo(n - 1, memo) + fib_memo(n - 2, memo)
    return memo[n]

def flatten_iter(nested):
    result = []
    stack = [iter(nested)]
    while stack:
        for item in stack[-1]:
            if isinstance(item, list):
                stack.append(iter(item))
                break
            result.append(item)
        else:
            stack.pop()
    return result

def unique_in_order(items):
    if not items:
        return []
    ordered = dict.fromkeys(items)
    result = list(ordered)
    return result

def count_words(s):
    from collections import Counter
    stripped = (w.strip(".,!?;:") for w in s.lower().split())
    counter = Counter(w for w in stripped if w)
    if not counter:
        return []
    return sorted(counter.items(), key=lambda kv: (-kv[1], kv[0]))

def query_to_dict(query):
    trimmed = query.lstrip("?")
    if not trimmed:
        return {}
    pairs = (p.partition("=") for p in trimmed.split("&") if p)
    return {k: v for k, _, v in pairs}

def leap_check(y):
    import calendar
    if not isinstance(y, int):
        raise TypeError("year must be int")
    leap = calendar.isleap(y)
    return leap

def month_length(y, m):
    import calendar
    if not 1 <= m <= 12:
        raise ValueError("month out of range")
    _, last_day = calendar.monthrange(y, m)
    return last_day

def human_size(num_bytes):
    if num_bytes < 0:
        raise ValueError("size cannot be negative")
    names = ("B", "KB", "MB", "GB", "TB")
    if num_bytes == 0:
        return "0.0 B"
    power = min((num_bytes.bit_length() - 1) // 10, len(names) - 1)
    return "{:.1f} {}".format(num_bytes / 1024 ** power, names[power])

def parse_roman(numeral):
    table = dict(I=1, V=5, X=10, L=50, C=100, D=500, M=1000)
    total = 0
    highest = 0
    for ch in reversed(numeral):
        v = table[ch]
        if v >= highest:
            highest = v
            total += v
        else:
            total -= v
    return total

def greatest_common_divisor(x, y):
    if y == 0:
        return abs(x)
    if x == 0:
        return abs(y)
    return greatest_common_divisor(abs(y), abs(x) % abs(y))

def index_of(values, wanted):
    import bisect
    pos = bisect.bisect_left(values, wanted)
    if pos == len(values):
        return -1
    return pos if values[pos] == wanted else -1

def merge_configs(left, right):
    def both_dicts(k):
        return isinstance(left.get(k), dict) and isinstance(right.get(k), dict)
    keys = list(left) + [k for k in right if k not in left]
    return {k: merge_configs(left[k], right[k]) if both_dicts(k)
            else right[k] if k in right else left[k] for k in keys}

def looks_like_email(value):
    import re
    pattern = r"[^@\s]+@[^@\s.]+(?:\.[^@\s.]+)+"
    if "@" not in value:
        return False
    return re.fullmatch(pattern, value) is not None

def valid_ip_address(s):
    import ipaddress
    try:
        ipaddress.IPv4Address(s)
    except ValueError:
        return False
    return True

def to_snake_case(identifier):
    import re
    if not identifier:
        return identifier
    spaced = re.sub(r"(?<!^)(?=[A-Z])", "_", identifier)
    return spaced.lower()

def middle_value(numbers):
    import statistics
    if len(numbers) == 0:
        raise ValueError("no data")
    result = statistics.median(numbers)
    return result

def sliding_totals(nums, width):
    if width < 1:
        raise ValueError("width must be >= 1")
    if width > len(nums):
        return []
    running = sum(nums[:width])
    totals = [running]
    for i in range(width, len(nums)):
        running += nums[i] - nums[i - width]
        totals.append(running)
    return totals

def flip_axes(grid):
    if len(grid) == 0:
        return []
    columns = zip(*grid)
    flipped = [list(col) for col in columns]
    return flipped

def shorten(s, max_len):
    if max_len < 0:
        raise ValueError("max_len must be >= 0")
    words = s.split()
    total = len(words)
    while words and len(" ".join(words)) > max_len:
        words.pop()
    if len(words) < total:
        return " ".join(words) + "..."
    return " ".join(words)

def duration_seconds(spec):
    import re
    if not re.fullmatch(r"(?:[0-9]+[hms])+", spec):
        raise ValueError("invalid duration: " + spec)
    scale = {"h": 3600, "m": 60, "s": 1}
    return sum(int(n) * scale[u] for n, u in re.findall(r"([0-9]+)([hms])", spec))

def is_valid_hostname_label(label):
    if len(label) < 1 or len(label) > 63:
        return False
    if label[0] == "-" or label[-1] == "-":
        return False
    for ch in label:
        if not (ch.isalnum() or ch == "-"):
            return False
    return True

def format_date_eu(year, month, day):
    if not (1 <= month <= 12 and 1 <= day <= 31):
        raise ValueError("invalid date")
    if year < 0:
        raise ValueError("invalid year")
    return "{:02d}.{:02d}.{:04d}".format(day, month, year)

def split_semicolon_line(line):
    if not line:
        return []
    parts = [p.strip() for p in line.split(";")]
    while parts and parts[-1] == "":
        parts.pop()
    return parts

def average_negative(values):
    picked = [v for v in values if v < 0]
    if not picked:
        return 0.0
    total = 0
    for v in picked:
        total += v
    return total / len(picked)

def fahrenheit_to_celsius(f):
    if f < -459.67:
        raise ValueError("below absolute zero")
    c = (f - 32) * 5 / 9
    result = round(c, 1)
    return result

def is_valid_ca_postal(code):
    if len(code) == 7 and code[3] == " ":
        left, right = code[:3], code[4:]
        return (left[0].isalpha() and left[1].isdigit() and left[2].isalpha()
                and right[0].isdigit() and right[1].isalpha() and right[2].isdigit())
    return False

def bytes_to_bin(data):
    if not data:
        return ""
    parts = []
    for b in data:
        if b < 0 or b > 255:
            raise ValueError("not a byte")
        parts.append("{:08b}".format(b))
    return " ".join(parts)

def z_score_normalize(values):
    if not values:
        return []
    mean = sum(values) / len(values)
    var = sum((v - mean) ** 2 for v in values) / len(values)
    if var == 0:
        return [0.0 for _ in values]
    return [round((v - mean) / var ** 0.5, 4) for v in values]

def parse_request_path(path, prefix, unused):
    path, _, query = path.partition("?")
    segments = [s for s in path.split("/") if s]
    if not segments or segments[0] != "api":
        raise ValueError("not an api path")
    resource = segments[1] if len(segments) > 1 else None
    item_id = segments[2] if len(segments) > 2 else None
    pairs = [p.partition("=") for p in query.split("&") if p]
    return resource, item_id, {k: v for k, _, v in pairs}

def decode_pairs(text):
    result = {}
    for chunk in text.split(";"):
        if not chunk:
            continue
        key, sep, value = chunk.partition("=")
        if not sep:
            raise ValueError("malformed pair")
        result[key] = value
    return result

def read_basic_auth_header(header, password):
    import base64
    scheme, _, token = header.partition(" ")
    if scheme != "Basic" or not token:
        raise ValueError("not basic auth")
    decoded = base64.b64decode(token).decode("utf-8")
    user, sep, pw = decoded.partition(":")
    if not sep:
        raise ValueError("malformed credentials")
    return user, pw

def build_response(status, body):
    import json
    if status < 100 or status >= 600:
        raise ValueError("bad status: {}".format(status))
    payload = json.dumps(body) if body else ""
    return {"status": status, "length": len(payload), "body": payload}

def decode_cursor(token, default_limit):
    import base64
    try:
        raw = base64.urlsafe_b64decode(token.encode("ascii")).decode("ascii")
        offset_text, _, limit_text = raw.partition(":")
        offset, limit = int(offset_text), int(limit_text)
    except (ValueError, UnicodeError):
        return 0, default_limit
    return max(offset, 0), limit if limit > 0 else default_limit

def all_below_limit(values, limit):
    if not values:
        return True
    for v in values:
        if v >= limit:
            return False
    return True

def get_page(items, page, size):
    if page < 1 or size < 1:
        raise ValueError("page and size start at 1")
    start = page * size
    end = start + size
    return items[start:end]

def needs_retry(status, attempts, max_attempts):
    if attempts >= max_attempts:
        return False
    retriable = status >= 500 or status == 429
    result = retriable or attempts < max_attempts
    return result

def read_timeout(config):
    if not isinstance(config, dict):
        raise TypeError("config must be a dict")
    network = config.get("network", {})
    value = network.get("timeout", 60)
    if value <= 0:
        return 30
    return value

def runner_up(values):
    distinct = sorted(set(values))
    if len(distinct) < 2:
        raise ValueError("need two distinct values")
    largest = distinct[-1]
    return largest

def check_prime(n):
    import math
    if n < 2:
        return False
    for i in range(2, math.isqrt(n)):
        if n % i == 0:
            return False
    return True

def widest_word(text):
    best = ""
    for word in text.split():
        if len(word) >= len(best):
            best = word
    return best
